WITH item_sales AS (SELECT cs.cs_call_center_sk, cs.cs_item_sk, SUM(cs.cs_net_paid) AS total_sales, SUM(cs.cs_net_profit) AS total_profit, SUM(cs.cs_quantity) AS total_qty FROM catalog_sales cs GROUP BY cs.cs_call_center_sk, cs.cs_item_sk), item_returns AS (SELECT cr.cr_call_center_sk, cr.cr_item_sk, COUNT(*) AS return_cnt, SUM(cr.cr_return_amount) AS total_return_amt, SUM(cr.cr_net_loss) AS total_return_loss FROM catalog_returns cr GROUP BY cr.cr_call_center_sk, cr.cr_item_sk), item_reason_counts AS (SELECT cr.cr_call_center_sk, cr.cr_item_sk, r.r_reason_desc, COUNT(*) AS cnt FROM catalog_returns cr JOIN reason r ON cr.cr_reason_sk = r.r_reason_sk GROUP BY cr.cr_call_center_sk, cr.cr_item_sk, r.r_reason_desc), item_reason AS (SELECT cr_call_center_sk, cr_item_sk, r_reason_desc, ROW_NUMBER() OVER (PARTITION BY cr_call_center_sk, cr_item_sk ORDER BY cnt DESC) AS rn FROM item_reason_counts) SELECT cc.cc_name, s.cs_item_sk AS item_sk, s.total_sales, s.total_profit, COALESCE(r.return_cnt,0) AS return_count, COALESCE(r.total_return_amt,0) AS return_amount, CASE WHEN s.total_profit >= 100000 THEN 'Very High' WHEN s.total_profit >= 50000 THEN 'High' WHEN s.total_profit >= 10000 THEN 'Medium' ELSE 'Low' END AS profit_category, DENSE_RANK() OVER (PARTITION BY cc.cc_name ORDER BY s.total_profit - COALESCE(r.total_return_loss,0) DESC) AS profit_rank, rr.r_reason_desc AS top_return_reason FROM call_center cc JOIN item_sales s ON cc.cc_call_center_sk = s.cs_call_center_sk LEFT JOIN item_returns r ON s.cs_call_center_sk = r.cr_call_center_sk AND s.cs_item_sk = r.cr_item_sk LEFT JOIN item_reason rr ON s.cs_call_center_sk = rr.cr_call_center_sk AND s.cs_item_sk = rr.cr_item_sk AND rr.rn = 1 WHERE s.total_sales > 0 ORDER BY cc.cc_name, profit_rank LIMIT 100
